from collections import deque
def enc(grid,bg=0,out=3):
    h,w=len(grid),len(grid[0]); seen=[[False]*w for _ in range(h)]; dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and grid[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True; dq.append((ni,nj))
    return [[out if grid[i][j]==bg and not seen[i][j] else grid[i][j] for j in range(w)] for i in range(h)]
def eq(a,b): return all(a[i][j]==b[i][j] for i in range(len(a)) for j in range(len(a[0])))
